  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multi-select challenge</p>
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="intro">Choose every answer that fits each question, then submit your responses.</p>

      <form id="quiz-form" novalidate>
