            <div class="choices">
              <label><input type="checkbox" name="programming-languages" value="python"> Python</label>
              <label><input type="checkbox" name="programming-languages" value="html"> HTML</label>
              <label><input type="checkbox" name="programming-languages" value="java"> Java</label>
              <label><input type="checkbox" name="programming-languages" value="css"> CSS</label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>Which languages are primarily used for styling or describing web content?</legend>
            <div class="choices">
              <label><input type="checkbox" name="web-content" value="css"> CSS</label>
              <label><input type="checkbox" name="web-content" value="html"> HTML</label>
              <label><input type="checkbox" name="web-content" value="ruby"> Ruby</label>
              <label><input type="checkbox" name="web-content" value="csharp"> C#</label>
            </div>
          </fieldset>
